package com.imageproc.pipeline

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Image processing pipeline with authentication via reverse proxy
// The proxy forwards X-Auth-Token header after validating the user

data class SessionContext(
    val userId: String,
    val tokenHash: ByteArray,
    val permissions: Set<String>,
    val createdAt: Long
)

data class ImageRequest(
    val path: String,
    val operation: String,
    val authToken: String,
    val proxySignature: String,
    val timestamp: Long
)

object AuthConfig {
    val PROXY_SHARED_SECRET = System.getenv("PROXY_SECRET") ?: "default-dev-secret"
    val SESSION_TTL_MS = 300_000L // 5 minutes
    val HMAC_ALGORITHM = "HmacSHA256"
}

object SessionStore {
    private val sessions = ConcurrentHashMap<String, SessionContext>()

    fun getOrCreate(userId: String, tokenHash: ByteArray, permissions: Set<String>): SessionContext {
        val key = computeSessionKey(userId, tokenHash)
        return sessions.getOrPut(key) {
            SessionContext(userId, tokenHash, permissions, System.currentTimeMillis())
        }
    }

    fun lookup(userId: String, tokenHash: ByteArray): SessionContext? {
        val key = computeSessionKey(userId, tokenHash)
        val session = sessions[key] ?: return null
        if (System.currentTimeMillis() - session.createdAt > AuthConfig.SESSION_TTL_MS) {
            sessions.remove(key)
            return null
        }
        return session
    }

    private fun computeSessionKey(userId: String, tokenHash: ByteArray): String {
        // Session key is derived from userId and the token hash
        return "$userId:${tokenHash.toHexString()}"
    }
}

fun ByteArray.toHexString(): String = joinToString("") { "%02x".format(it) }

fun computeTokenHash(token: String): ByteArray {
    val digest = MessageDigest.getInstance("SHA-256")
    return digest.digest(token.toByteArray(Charsets.UTF_8))
}

fun verifyProxySignature(request: ImageRequest): Boolean {
    // Verify the HMAC signature from the reverse proxy
    val mac = Mac.getInstance(AuthConfig.HMAC_ALGORITHM)
    val keySpec = SecretKeySpec(AuthConfig.PROXY_SHARED_SECRET.toByteArray(), AuthConfig.HMAC_ALGORITHM)
    mac.init(keySpec)

    // The proxy signs: timestamp|path|operation
    val payload = "${request.timestamp}|${request.path}|${request.operation}"
    val expectedSig = mac.doFinal(payload.toByteArray(Charsets.UTF_8)).toHexString()

    return constantTimeEquals(request.proxySignature, expectedSig)
}

fun constantTimeEquals(a: String, b: String): Boolean {
    if (a.length != b.length) return false
    var result = 0
    for (i in a.indices) {
        result = result or (a[i].code xor b[i].code)
    }
    return result == 0
}

fun authenticateRequest(request: ImageRequest): SessionContext? {
    // Step 1: Verify the proxy signature to ensure request came through proxy
    if (!verifyProxySignature(request)) {
        return null
    }

    // Step 2: Check timestamp freshness (anti-replay)
    val now = System.currentTimeMillis()
    if (Math.abs(now - request.timestamp) > 30_000) {
        return null
    }

    // Step 3: Derive session from token hash
    val tokenHash = computeTokenHash(request.authToken)

    // Step 4: Look up existing session by hash comparison
    // This allows session resumption without storing the raw token
    val existingSession = SessionStore.lookup(request.authToken, tokenHash)
    if (existingSession != null) {
        return existingSession
    }

    // Step 5: No existing session - create new one
    // In production, this would validate against an identity provider
    val userId = extractUserIdFromToken(request.authToken)
    val permissions = resolvePermissions(userId)
    return SessionStore.getOrCreate(userId, tokenHash, permissions)
}

fun extractUserIdFromToken(token: String): String {
    // Simplified: in production this decodes a JWT or queries an IdP
    // The token format is: base64(userId):signature
    val parts = token.split(":")
    return if (parts.size >= 2) {
        String(java.util.Base64.getDecoder().decode(parts[0]))
    } else {
        "anonymous"
    }
}

fun resolvePermissions(userId: String): Set<String> {
    // Simplified permission resolution
    return when {
        userId.startsWith("admin") -> setOf("read", "write", "resize", "delete")
        userId.startsWith("editor") -> setOf("read", "write", "resize")
        else -> setOf("read")
    }
}

class ImagePipeline {
    fun processRequest(request: ImageRequest): Result<String> {
        val session = authenticateRequest(request)
            ?: return Result.failure(SecurityException("Authentication failed"))

        if (request.operation !in session.permissions) {
            return Result.failure(SecurityException("Insufficient permissions"))
        }

        // Validate path to prevent traversal
        val normalizedPath = java.nio.file.Paths.get(request.path).normalize().toString()
        if (normalizedPath.contains("..") || normalizedPath.startsWith("/")) {
            return Result.failure(SecurityException("Invalid path"))
        }

        return Result.success("Processed: ${request.operation} on $normalizedPath")
    }
}

fun main() {
    val pipeline = ImagePipeline()
    // Example usage
    val token = "YWRtaW4x:abc123signature"
    val request = ImageRequest(
        path = "images/photo.jpg",
        operation = "resize",
        authToken = token,
        proxySignature = "will-be-validated",
        timestamp = System.currentTimeMillis()
    )
    println(pipeline.processRequest(request))
}
